CREATE TABLE public.payment_image_checks(message_id uuid PRIMARY KEY REFERENCES public.messages(id),payer_id uuid NOT NULL REFERENCES public.profiles(id),entered_upi text NOT NULL,observed_upi text NOT NULL,observed_utr text NOT NULL,match_status text NOT NULL CHECK(match_status IN('matched','mismatch','suspected_edit','unreadable')),created_at timestamptz NOT NULL DEFAULT now());
REVOKE ALL ON public.payment_image_checks FROM PUBLIC,anon,authenticated;
GRANT SELECT ON public.payment_image_checks TO authenticated;
GRANT ALL ON public.payment_image_checks TO service_role;
ALTER TABLE public.payment_image_checks ENABLE ROW LEVEL SECURITY;
CREATE POLICY private_payment_check ON public.payment_image_checks FOR SELECT TO authenticated USING(payer_id=auth.uid() OR public.has_role(auth.uid(),'admin'));
CREATE FUNCTION public.require_matched_payment_image() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.payment_image_checks c JOIN public.messages m ON m.id=c.message_id WHERE c.message_id=NEW.message_id AND c.payer_id=NEW.payer_id AND m.sender_id=NEW.payer_id AND m.image_path LIKE NEW.payer_id::text||'/%' AND c.match_status='matched' AND c.observed_utr=NEW.reference AND lower(c.entered_upi)=lower(c.observed_upi)) THEN RAISE EXCEPTION 'MATCHED_SCREENSHOT_REQUIRED'; END IF; RETURN NEW; END $$;
CREATE TRIGGER require_matched_payment_image BEFORE INSERT OR UPDATE OF message_id ON public.membership_requests FOR EACH ROW EXECUTE FUNCTION public.require_matched_payment_image();
REVOKE ALL ON FUNCTION public.require_matched_payment_image() FROM PUBLIC,anon,authenticated;
CREATE FUNCTION public.confirm_edited_payment_image(_message uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE payer uuid; BEGIN IF NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'ADMIN_ONLY'; END IF; SELECT c.payer_id INTO payer FROM public.payment_image_checks c JOIN public.messages m ON m.id=c.message_id WHERE c.message_id=_message AND m.sender_id=c.payer_id FOR UPDATE OF c; IF payer IS NULL THEN RAISE EXCEPTION 'EVIDENCE_REQUIRED'; END IF; UPDATE public.membership_access SET revoked_at=now() WHERE request_id IN(SELECT id FROM public.membership_requests WHERE payer_id=payer); UPDATE public.membership_requests SET status='rejected',reviewed_at=now(),reviewed_by=auth.uid(),note='నిర్వాహకుడు మార్చిన చిత్రంగా నిర్ధారించారు' WHERE payer_id=payer AND status='pending'; PERFORM public.block_confirmed_content(payer,'నిర్వాహకుడు మార్చిన చెల్లింపు చిత్రంగా నిర్ధారించారు'); END $$;
REVOKE ALL ON FUNCTION public.confirm_edited_payment_image(uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.confirm_edited_payment_image(uuid) TO authenticated,service_role;